155:         make(2, MID + 1.6, 'rush', 91), make(2, MID + 4.8, 'rush', 99),
156:         make(6, MID - 7, 'linebacker', 51), make(6, MID, 'linebacker', 54), make(6, MID + 7, 'linebacker', 58),
157:         make(4, 6, 'corner', 21), make(4, FIELD_HEIGHT - 6, 'corner', 24),
158:         make(12, MID - 10, 'safety', 29), make(12, MID + 10, 'safety', 32)
