import { createRequire } from 'node:module';
import { mkdirSync, statSync } from 'node:fs';
const root = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(root + '/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({headless:true});
const errors=[];
const page=await browser.newPage({viewport:{width:1200,height:900}, deviceScaleFactor:1});
page.on('pageerror',e=>errors.push('pageerror '+e.message));
page.on('response',r=>{if(r.status()>=400 && new URL(r.url()).origin==='http://127.0.0.1:3000')errors.push('HTTP '+r.status()+' '+r.url())});
await page.goto('http://127.0.0.1:3000/',{waitUntil:'networkidle'});
await page.evaluate(()=>localStorage.removeItem('gridiron-glory-save'));
await page.reload({waitUntil:'networkidle'});
await page.evaluate(()=>document.fonts.ready);
const desktop=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,field:{width:document.querySelector('#field').getBoundingClientRect().width,height:document.querySelector('#field').getBoundingClientRect().height},title:document.title}));
mkdirSync('/tmp/opencode',{recursive:true});
const screenshot='/tmp/opencode/gridiron-latest.jpg';
await page.screenshot({path:screenshot,type:'jpeg',quality:78});
const mobile=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
mobile.on('pageerror',e=>errors.push('mobile pageerror '+e.message));
mobile.on('response',r=>{if(r.status()>=400 && new URL(r.url()).origin==='http://127.0.0.1:3000')errors.push('mobile HTTP '+r.status()+' '+r.url())});
await mobile.goto('http://127.0.0.1:3000/',{waitUntil:'networkidle'});
await mobile.evaluate(()=>document.fonts.ready);
const before=await mobile.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,controls:getComputedStyle(document.querySelector('.touch-controls')).display,visible:(()=>{const r=document.querySelector('[data-dir="right"]').getBoundingClientRect();return r.width>0&&r.height>0})()}));
await mobile.locator('#snap-btn').click();
const start=await mobile.locator('#field-status').textContent();
const button=mobile.locator('[data-dir="right"]');
const box=await button.boundingBox();
await mobile.mouse.move(box.x+box.width/2,box.y+box.height/2);
await mobile.mouse.down();
await mobile.waitForTimeout(700);
await mobile.mouse.up();
await mobile.waitForTimeout(4000);
const after=await mobile.evaluate(()=>({status:document.querySelector('#field-status').textContent,plays:JSON.parse(localStorage.getItem('gridiron-glory-save')||'{}').plays,progress:document.querySelector('#situation').textContent.trim()}));
console.log(JSON.stringify({desktop,mobile:before,touchRun:{start,after},errors,screenshot,size:statSync(screenshot).size},null,2));
await browser.close();
